/**
 * A server that does not serve {@code /repositories/<id>/config} must not make the Summary page log warnings.
 */
class SummaryServletRemoteConfigUnavailableTest {

	private ListAppender<ILoggingEvent> appender;

	private Logger logger;

	@BeforeEach
	void attachAppender() {
		logger = (Logger) LoggerFactory.getLogger(SummaryServlet.class);
		appender = new ListAppender<>();
		appender.start();
		logger.addAppender(appender);
	}

	@AfterEach
	void cleanUp() {
		logger.detachAppender(appender);
		appender.stop();
	}

	@ParameterizedTest
	@ValueSource(ints = { 404, 405, 501 })
	void summaryRendersAndLogsNoWarningWhenTheServerCannotServeTheConfiguration(int status) throws Exception {
		// Sockets cannot be bound in every build sandbox, so the manager fails the way the HTTP session does when the
		// server answers /repositories/remote/config with the given status.
		RemoteRepositoryManager manager = new RemoteRepositoryManager("http://localhost/rdf4j-server") {
			@Override
			public RepositoryConfig getRepositoryConfig(String id) {
				throw new RepositoryException(
						"Request failed with status " + status + ": http://localhost/rdf4j-server/repositories/" + id
								+ "/config");
			}
		};
		try {
			RepositoryInfo info = new RepositoryInfo();
			info.setId("remote");
			info.setDescription("Remote repo");
			SummaryServlet servlet = new SummaryServlet();
			servlet.setRepositoryManager(manager);
			servlet.setRepositoryInfo(info);

			ByteArrayOutputStream buffer = new ByteArrayOutputStream();
			TupleResultBuilder builder = new TupleResultBuilder(new WorkbenchTupleResultWriter(buffer),
					SimpleValueFactory.getInstance());
			servlet.service(builder);

			assertThat(buffer.toString(StandardCharsets.UTF_8))
					.contains("remote")
					.doesNotContain("config-model-turtle");
			assertThat(appender.list)
					.filteredOn(event -> event.getLevel().isGreaterOrEqual(Level.WARN))
					.isEmpty();
		} finally {
			manager.shutDown();
		}
	}

	@Test
	void infoServletDoesNotFailWhenConfigEndpointIsMissing() throws Exception {
		RemoteRepositoryManager manager = new RemoteRepositoryManager("http://localhost/rdf4j-server") {
			@Override
			public boolean hasRepositoryConfig(String id) {
				return true;
			}

			@Override
			public RepositoryConfig getRepositoryConfig(String id) {
				throw new RepositoryException("Request failed with status 404: config endpoint is missing");
			}
		};
		try {
			InfoServlet servlet = new InfoServlet();
			servlet.setRepositoryInfo(new RepositoryInfo());
			servlet.setRepositoryManager(manager);
			MockServletContext context = new MockServletContext();
			context.setAttribute(WorkbenchPolicyLoader.POLICY_ATTRIBUTE,
					WorkbenchPolicy.fromProperties(new Properties(), Set.of()));
			servlet.init(new TestServletConfig("info", context, Map.of("transformations", "/transform")));
			WorkbenchRequest req = mock(WorkbenchRequest.class);
			HttpServletResponse resp = mock(HttpServletResponse.class);
			when(resp.getOutputStream()).thenReturn(mock(ServletOutputStream.class));

			assertThatCode(() -> servlet.service(req, resp)).doesNotThrowAnyException();
		} finally {
			manager.shutDown();
		}
	}
}
